using System; using System.Collections.Generic;
namespace CodexTrayStatus { internal static class QuotaForecastService {
internal static List<QuotaForecast> Evaluate(QuotaHistoryResult history, AppSnapshot snapshot, long now) { List<QuotaForecast> output=new List<QuotaForecast>(); if(history==null||!history.Available||snapshot==null||snapshot.Quota==null||snapshot.Quota.Limits==null)return output; foreach(RateLimitWindow window in snapshot.Quota.Limits) { if(window==null||string.IsNullOrEmpty(window.WindowKey)||!window.ResetsAt.HasValue)continue; ValidityResult validity=DataFreshness.EvaluateQuota(window,snapshot.QuotaState,now); if(!validity.IsUsable)continue; List<QuotaHistoryPoint> rows=history.Points.FindAll(delegate(QuotaHistoryPoint p){return p.WindowKey==window.WindowKey&&p.CycleEnd==window.ResetsAt.Value;}); rows.Sort(delegate(QuotaHistoryPoint a,QuotaHistoryPoint b){return a.ObservedAt.CompareTo(b.ObservedAt);}); QuotaForecast value=new QuotaForecast{WindowKey=window.WindowKey,ResetsAt=window.ResetsAt.Value,SampleCount=rows.Count,Status="insufficient"}; if(rows.Count<2||rows[rows.Count-1].ObservedAt-rows[0].ObservedAt<300000){output.Add(value);continue;} QuotaHistoryPoint first=rows[0],last=rows[rows.Count-1]; double rate=(last.UsedPercent-first.UsedPercent)/((last.ObservedAt-first.ObservedAt)/3600000d); if(double.IsNaN(rate)||double.IsInfinity(rate)||rate<=0.05){value.Status="idle";output.Add(value);continue;} value.UsedPercentPerHour=rate; value.EstimatedExhaustedAt=last.ObservedAt+(long)Math.Round((100d-last.UsedPercent)/rate*3600000d); value.Status=value.EstimatedExhaustedAt<=value.ResetsAt?"before_reset":"after_reset"; output.Add(value);} return output; }
} }
